css:
.lakesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #143142;
    background: linear-gradient(180deg, #f3f9fb 0%, #e9f3f6 100%);
    border-radius: 18px;
}

.lakesim-container * {
    box-sizing: border-box;
}

.lakesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0e7c86 0%, #15a3a0 55%, #1ec1ad 100%);
    color: #f3fffe;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 30px rgba(14, 124, 134, 0.28);
}

.lakesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.lakesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #eafffd;
    background: rgba(255, 255, 255, 0.16);
    border: 1px solid rgba(255, 255, 255, 0.35);
    padding: 5px 14px;
    border-radius: 999px;
}

.lakesim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e7fbf9;
}

.lakesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4d6f7e;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.lakesim-period-counter #currentDay,
.lakesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0e7c86;
}

.lakesim-round-name {
    background: rgba(14, 124, 134, 0.12);
    color: #0e7c86;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.lakesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b4531a;
    background: rgba(232, 122, 47, 0.14);
    border: 1px solid rgba(232, 122, 47, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.lakesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.lakesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6e7ec;
    box-shadow: 0 6px 16px rgba(20, 49, 66, 0.07);
    border-top: 4px solid #15a3a0;
}

.lakesim-card-coverage { border-top-color: #0e7c86; }
.lakesim-card-wellbeing { border-top-color: #2bb673; }
.lakesim-card-retention { border-top-color: #e87a2f; }
.lakesim-card-trust { border-top-color: #4a78c9; }

.lakesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b8593;
}

.lakesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #143142;
    font-variant-numeric: tabular-nums;
}

.lakesim-card-coverage .lakesim-value { color: #0e7c86; }
.lakesim-card-wellbeing .lakesim-value { color: #2bb673; }
.lakesim-card-retention .lakesim-value { color: #e87a2f; }
.lakesim-card-trust .lakesim-value { color: #4a78c9; }

.lakesim-sublabel {
    font-size: 0.76rem;
    color: #7c95a2;
    line-height: 1.35;
}

/* state-driven KPI colouring */
.lakesim-coverage-danger { border-top-color: #d14343; }
.lakesim-coverage-danger .lakesim-value { color: #d14343; }
.lakesim-coverage-safe { border-top-color: #2bb673; }
.lakesim-coverage-safe .lakesim-value { color: #2bb673; }

.lakesim-wellbeing-danger { border-top-color: #d14343; }
.lakesim-wellbeing-danger .lakesim-value { color: #d14343; }
.lakesim-wellbeing-safe { border-top-color: #2bb673; }
.lakesim-wellbeing-safe .lakesim-value { color: #2bb673; }

.lakesim-retention-high { border-top-color: #d14343; }
.lakesim-retention-high .lakesim-value { color: #d14343; }
.lakesim-retention-low { border-top-color: #2bb673; }
.lakesim-retention-low .lakesim-value { color: #2bb673; }

.lakesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #d6e7ec;
    color: #2b4a5a;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    box-shadow: 0 4px 12px rgba(20, 49, 66, 0.05);
}

.lakesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #0e7c86;
}

.lakesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #15a3a0;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(20, 49, 66, 0.07);
}

.lakesim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.lakesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0e7c86;
    margin-bottom: 6px;
}

.lakesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2f4d5c;
}

.lakesim-briefing-text strong { color: #0e7c86; }
.lakesim-briefing-text em { color: #b4531a; font-style: italic; }

.lakesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6e7ec;
    box-shadow: 0 6px 16px rgba(20, 49, 66, 0.07);
}

.lakesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #143142;
    border-bottom: 2px solid #e2eef2;
    padding-bottom: 8px;
}

.lakesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #284a5b;
    margin: 14px 0 6px;
}

.lakesim-container select,
.lakesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcd6de;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7fcfd;
    color: #143142;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.lakesim-container select:focus,
.lakesim-container input[type="number"]:focus {
    outline: none;
    border-color: #15a3a0;
    box-shadow: 0 0 0 3px rgba(21, 163, 160, 0.18);
}

.lakesim-container select option {
    background-color: #ffffff;
    color: #143142;
}

.lakesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #0e7c86;
}

.lakesim-range-readout,
.lakesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4d6f7e;
    margin-top: 4px;
}

.lakesim-range-readout span:last-child,
.lakesim-alloc-readout span:nth-child(2) {
    color: #0e7c86;
    font-weight: 800;
}

.lakesim-hint {
    font-size: 0.8rem;
    color: #7c95a2;
    margin-top: 4px;
    line-height: 1.4;
}

.lakesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.lakesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f3f9fb;
    border: 1px solid #d6e7ec;
    border-radius: 9px;
    padding: 8px 12px;
}

.lakesim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2f4d5c;
}

.lakesim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.lakesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.lakesim-container .btn-primary {
    background: linear-gradient(135deg, #0e7c86 0%, #1ec1ad 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(14, 124, 134, 0.32);
}

.lakesim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.lakesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcd6de;
    color: #4d6f7e;
    background: transparent;
}

.lakesim-coach {
    background: linear-gradient(160deg, #103c46 0%, #0e2d39 100%);
    color: #dceef2;
    border: 1px solid #1b4f5a;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(14, 45, 57, 0.28);
}

.lakesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #4fd6c4;
    margin-bottom: 8px;
}

.lakesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.lakesim-coach-body strong { color: #4fd6c4; }
.lakesim-coach-body em { color: #ffc46b; font-style: italic; }

.lakesim-history,
.lakesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6e7ec;
    box-shadow: 0 6px 16px rgba(20, 49, 66, 0.07);
}

.lakesim-history h3,
.lakesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #143142;
}

.lakesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2f4d5c;
}

.lakesim-container table#usfHistoryTable th {
    background: #eef7f9;
    color: #0e7c86;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6e7ec;
}

.lakesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e6f1f4;
    color: #2f4d5c;
}

.lakesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7fbfc;
}

.lakesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .lakesim-container {
        padding: 14px;
    }
    .lakesim-header h1 {
        font-size: 1.7rem;
    }
    .lakesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .lakesim-value {
        font-size: 2rem;
    }
    .lakesim-clock {
        margin-left: 0;
    }
    .lakesim-period-counter {
        font-size: 0.88rem;
    }
    .lakesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .lakesim-alloc-row {
        flex-wrap: wrap;
    }
    .lakesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .lakesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.lakesim-cm { background:#f2f7f8; color:#12222a; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.lakesim-cm-head { text-align:center; border-bottom:1px solid #d6e4e8; padding-bottom:14px; margin-bottom:16px; }
.lakesim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#4d6570; font-weight:700; }
.lakesim-cm-scorewrap { margin:8px 0 2px; }
.lakesim-cm-score { font-size:52px; font-weight:800; color:#2b6c82; line-height:1; }
.lakesim-cm-score-max { font-size:20px; color:#7f929a; font-weight:600; }
.lakesim-cm-grade { font-size:19px; font-weight:700; color:#12222a; margin-top:4px; }
.lakesim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.lakesim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.lakesim-cm-met { background:#cfe9df; color:#1c6b52; }
.lakesim-cm-fail { background:#f6ddd8; color:#a4392f; }
.lakesim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.lakesim-cm-metric { background:#e6f0f2; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.lakesim-cm-metric-val { font-size:22px; font-weight:800; color:#12222a; }
.lakesim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#4d6570; margin-top:3px; }
.lakesim-cm-insights { background:#e6f0f2; border-radius:10px; padding:14px 18px; }
.lakesim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#4d6570; font-weight:700; margin-bottom:8px; }
.lakesim-cm-insights ul { margin:0; padding-left:18px; }
.lakesim-cm-insights li { font-size:14px; line-height:1.5; color:#28383a; margin-bottom:7px; }

