(function() {
    'use strict';

    class LakeshoreAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Talent Under Pressure`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Lakeshore Regional Health — Medicine & Acute Care).
            this.STAB_BUDGET = 1.4;          // CAD 1.4M in-year stabilisation flexibility (hard cap)
            this.RN_REPLACE = 65000;         // CAD 65,000 to replace one experienced RN
            this.WELLBEING_TARGET = 65;      // network well-being target
            this.SAFE_RATIO = 4;             // 1:4 medicine safe nurse-to-patient ratio

            // Concept truths (the right answers per the facilitator decision tree).
            this.TRUE_DIAG = `competency`;
            this.TRUE_MODEL = `team`;
            this.TRUE_STANCE = `scoped`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    coverage: 62,            // competency coverage on the worst unit (%)
                    wellbeing: 41,           // staff well-being index (0–100)
                    retention: 70,           // turnover-intent / retention risk (0–100, lower better)
                    trust: 35,               // frontline & union trust in leadership and AI (0–100)
                    budgetUsed: 0,           // CAD M of stabilisation budget committed
                    chasedAgency: false,
                    burnoutDeepened: false,
                    aiSilverBullet: false,
                    dividendExtracted: false,
                    throughputOnly: false,
                    coverageHistory: [62],
                    wellbeingHistory: [41],
                    retentionHistory: [70],
                    trustHistory: [35],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately WRONG-leaning click-through mix —
                // headcount framing, throughput squeeze, full AI go, extract dividend.
                // A blind click cannot auto-win.
                state.decisions = {
                    diag: `headcount`,
                    critical: `generic`,
                    cliff: 40,
                    model: `squeeze`,
                    precept: 0.4,
                    allied: 0.4,
                    retain: 0.6,
                    autonomy: `strip`,
                    stance: `fullgo`,
                    usecase: `clinical`,
                    guardrails: `autopilot`,
                    dividend: `extract`,
                    sequence: `aifirst`,
                    dashboard: `throughput`,
                    pitch: `rosy`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dg = document.getElementById(`diagInput`);
                const cr = document.getElementById(`criticalInput`);
                const cl = document.getElementById(`cliffInput`);
                if (dg) decisions.diag = dg.value;
                if (cr) decisions.critical = cr.value;
                if (cl) decisions.cliff = parseInt(cl.value, 10);
                if (!Number.isFinite(decisions.cliff) || decisions.cliff < 0 || decisions.cliff > 100) {
                    warn(`warn_cliff_range`); return false;
                }
            } else if (round === 2) {
                const md = document.getElementById(`modelInput`);
                const pr = document.getElementById(`preceptInput`);
                const al = document.getElementById(`alliedInput`);
                const rt = document.getElementById(`retainInput`);
                const au = document.getElementById(`autonomyInput`);
                if (md) decisions.model = md.value;
                if (pr) decisions.precept = parseFloat(pr.value);
                if (al) decisions.allied = parseFloat(al.value);
                if (rt) decisions.retain = parseFloat(rt.value);
                if (au) decisions.autonomy = au.value;
                const parts = [decisions.precept, decisions.allied, decisions.retain];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.precept + decisions.allied + decisions.retain) * 100) / 100;
                if (Math.abs(total - this.STAB_BUDGET) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const st = document.getElementById(`stanceInput`);
                const uc = document.getElementById(`usecaseInput`);
                const gd = document.getElementById(`guardrailsInput`);
                const dv = document.getElementById(`dividendInput`);
                if (st) decisions.stance = st.value;
                if (uc) decisions.usecase = uc.value;
                if (gd) decisions.guardrails = gd.value;
                if (dv) decisions.dividend = dv.value;
                if (!decisions.stance) { warn(`warn_stance_missing`); return false; }
            } else if (round === 4) {
                const sq = document.getElementById(`sequenceInput`);
                const db = document.getElementById(`dashboardInput`);
                const pt = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sq) decisions.sequence = sq.value;
                if (db) decisions.dashboard = db.value;
                if (pt) decisions.pitch = pt.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let covDelta = 0, wbDelta = 0, retDelta = 0, trustDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: competency-distribution vs headcount (Common Error 1).
                switch (d.diag) {
                    case `competency`: covDelta += 8; trustDelta += 6; retDelta -= 4; coachKey = `coach_r1_competency`; break;
                    case `headcount`: ds.chasedAgency = true; covDelta -= 2; retDelta += 4; trustDelta -= 3; coachKey = `coach_r1_headcount`; break;
                    case `ratio`: covDelta -= 4; wbDelta -= 4; retDelta += 6; coachKey = `coach_r1_ratio`; break;
                    case `morale`: covDelta -= 2; wbDelta += 2; retDelta += 3; coachKey = `coach_r1_morale`; break;
                }

                // Flag the most safety-critical competency loss.
                switch (d.critical) {
                    case `seniority`: covDelta += 6; trustDelta += 4; if (d.diag === `competency`) coachKey = `coach_r1_sharp`; break;
                    case `generic`: covDelta -= 4; retDelta += 3; break;
                    case `documentation`: covDelta -= 2; break;
                    case `none`: covDelta -= 6; retDelta += 6; coachKey = `coach_r1_none`; break;
                }

                // Take the retention cliff / burnout spiral seriously.
                if (d.cliff >= 60) { retDelta -= 8; wbDelta += 4; trustDelta += 3; }
                else if (d.cliff <= 25) { retDelta += 8; wbDelta -= 3; coachKey = `coach_r1_cliffignored`; }

                summaryKey = (d.diag === `competency` && d.critical === `seniority`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Redesign the model of care (Common Errors 1 & 2).
                switch (d.model) {
                    case `team`: covDelta += 12; wbDelta += 4; retDelta -= 5; trustDelta += 4; coachKey = `coach_r2_team`; break;
                    case `squeeze`: covDelta += 6; wbDelta -= 12; retDelta += 10; trustDelta -= 6; ds.burnoutDeepened = true; coachKey = `coach_r2_squeeze`; break;
                    case `agency`: ds.chasedAgency = true; covDelta -= 6; wbDelta -= 6; retDelta += 8; coachKey = `coach_r2_agency`; break;
                    case `float`: covDelta += 4; wbDelta -= 5; retDelta += 4; coachKey = `coach_r2_float`; break;
                }

                // Skill-mix allocation under the CAD 1.4M cap.
                const pc = d.precept, al = d.allied, rt = d.retain;
                covDelta += pc * 9 + al * 6;          // preceptorship protects competency transfer; allied scope offloads safely
                wbDelta += rt * 7 + al * 2 - 0;       // retention/well-being spend lifts the index
                retDelta += -(rt * 9) - (pc * 3);     // retention spend and a credible pipeline hold the cliff
                trustDelta += rt * 3 + pc * 2;
                spend += pc + al + rt;

                if (pc <= 0.1) { covDelta -= 5; coachKey = `coach_r2_noprecept`; }   // starving preceptorship strands competency transfer
                if (rt <= 0.1) { retDelta += 6; wbDelta -= 4; }                       // starving retention feeds the cliff

                // Autonomy is a burnout safeguard (Common Error 2).
                switch (d.autonomy) {
                    case `protect`: wbDelta += 8; retDelta -= 6; trustDelta += 5; break;
                    case `partial`: wbDelta += 1; break;
                    case `strip`: wbDelta -= 10; retDelta += 8; trustDelta -= 4; ds.burnoutDeepened = true; if (coachKey === `coach_r2_team`) coachKey = `coach_r2_stripautonomy`; break;
                }

                summaryKey = (d.model === `team` && d.autonomy === `protect` && rt >= 0.4) ? `sum_r2_good` :
                             (ds.burnoutDeepened ? `sum_r2_burnout` : `sum_r2_weak`);
            } else if (round === 3) {
                // AI-adoption stance under a trust constraint (Common Errors 3 & 4).
                switch (d.stance) {
                    case `scoped`: covDelta += 4; wbDelta += 4; trustDelta += 8; retDelta -= 3; coachKey = `coach_r3_scoped`; break;
                    case `fullgo`: ds.aiSilverBullet = true; covDelta += 2; wbDelta -= 8; trustDelta -= 14; retDelta += 8; coachKey = `coach_r3_fullgo`; break;
                    case `defer`: trustDelta += 2; coachKey = `coach_r3_defer`; break;       // keeps peace but adds no capacity
                    case `no`: wbDelta -= 2; trustDelta += 1; coachKey = `coach_r3_no`; break; // a stance, but forgoes real relief
                }

                // First use-case (only meaningful if proceeding).
                if (d.stance === `scoped` || d.stance === `fullgo`) {
                    switch (d.usecase) {
                        case `scheduling`: wbDelta += 6; trustDelta += 4; retDelta -= 3; break;   // lower-risk, relieves the rota
                        case `clinical`: trustDelta -= 8; wbDelta -= 2; if (coachKey !== `coach_r3_fullgo`) coachKey = `coach_r3_clinicalfirst`; break;
                        case `none`: trustDelta -= 4; break;                                       // contradiction: proceeding but deploying nothing
                    }
                } else if (d.usecase !== `none`) {
                    // chose not to proceed yet named a use-case — minor incoherence
                    trustDelta -= 1;
                }

                // Responsible-AI guardrails (human-in-the-loop, override, accountability).
                if (d.stance === `scoped` || d.stance === `fullgo`) {
                    switch (d.guardrails) {
                        case `full`: trustDelta += 10; wbDelta += 3; covDelta += 2; break;
                        case `vague`: trustDelta -= 4; break;
                        case `autopilot`: trustDelta -= 12; covDelta -= 4; ds.aiSilverBullet = true; if (coachKey === `coach_r3_scoped`) coachKey = `coach_r3_noguardrails`; break;
                    }
                }

                // Where the AI time-savings go (Common Error 4: extract the dividend).
                if (d.stance === `scoped` || d.stance === `fullgo` || d.stance === `defer`) {
                    switch (d.dividend) {
                        case `reinvest`: wbDelta += 8; retDelta -= 8; trustDelta += 10; break;
                        case `vague`: trustDelta -= 3; break;
                        case `extract`: ds.dividendExtracted = true; wbDelta -= 6; retDelta += 10; trustDelta -= 14; coachKey = `coach_r3_extract`; break;
                    }
                }

                summaryKey = (d.stance === `scoped` && d.guardrails === `full` && d.dividend === `reinvest`) ? `sum_r3_good` :
                             (ds.dividendExtracted ? `sum_r3_extract` :
                             (ds.aiSilverBullet ? `sum_r3_silverbullet` : `sum_r3_weak`));
            } else if (round === 4) {
                // Integrate the plan, set the dashboard, pitch the CEO (Common Error 5).
                switch (d.sequence) {
                    case `stabilise`: covDelta += 6; wbDelta += 6; retDelta -= 6; trustDelta += 5; coachKey = `coach_r4_stabilise`; break;
                    case `aifirst`: trustDelta -= 8; wbDelta -= 4; coachKey = `coach_r4_aifirst`; break;
                    case `throughput`: wbDelta -= 8; retDelta += 8; trustDelta -= 5; coachKey = `coach_r4_throughputseq`; break;
                }

                // The CEO dashboard — leading well-being/turnover indicators vs throughput-only (Common Error 5).
                switch (d.dashboard) {
                    case `balanced`: wbDelta += 6; retDelta -= 6; trustDelta += 8; coachKey = `coach_r4_balanced`; break;
                    case `throughput`: ds.throughputOnly = true; wbDelta -= 5; retDelta += 8; trustDelta -= 6; coachKey = `coach_r4_throughputdash`; break;
                    case `financial`: ds.throughputOnly = true; wbDelta -= 3; retDelta += 5; trustDelta -= 4; break;
                }

                // CEO pitch posture.
                switch (d.pitch) {
                    case `honest`: trustDelta += 8; retDelta -= 4; if (d.dashboard === `balanced` && d.sequence === `stabilise`) coachKey = `coach_r4_ceowin`; break;
                    case `rosy`: trustDelta -= 6; retDelta += 4; coachKey = `coach_r4_rosy`; break;
                    case `defensive`: trustDelta -= 4; covDelta -= 2; break;
                }

                if (d.conviction >= 60) { wbDelta += 4; retDelta -= 4; trustDelta += 3; }
                else if (d.conviction <= 25) { wbDelta -= 4; retDelta += 4; trustDelta -= 3; }

                summaryKey = (d.sequence === `stabilise` && d.dashboard === `balanced` && d.pitch === `honest`) ? `sum_r4_good` :
                             (ds.throughputOnly ? `sum_r4_throughput` : `sum_r4_weak`);
            }

            // Resource accounting: the CAD 1.4M stabilisation budget is metered in R2.
            ds.budgetUsed = Math.min(this.STAB_BUDGET, Math.round((ds.budgetUsed + spend) * 100) / 100);

            // Apply deltas, clamped 0–100. Coverage can exceed 100% requirement only conceptually;
            // hold it to 100 for the index.
            ds.coverage = Math.max(0, Math.min(100, Math.round(ds.coverage + covDelta)));
            ds.wellbeing = Math.max(0, Math.min(100, Math.round(ds.wellbeing + wbDelta)));
            ds.retention = Math.max(0, Math.min(100, Math.round(ds.retention + retDelta)));
            ds.trust = Math.max(0, Math.min(100, Math.round(ds.trust + trustDelta)));

            ds.coverageHistory.push(ds.coverage);
            ds.wellbeingHistory.push(ds.wellbeing);
            ds.retentionHistory.push(ds.retention);
            ds.trustHistory.push(ds.trust);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                coverage: ds.coverage,
                coverageDelta: Math.round(covDelta),
                wellbeing: ds.wellbeing,
                wellbeingDelta: Math.round(wbDelta),
                retention: ds.retention,
                retentionDelta: Math.round(retDelta),
                trust: ds.trust,
                trustDelta: Math.round(trustDelta),
                budgetUsed: ds.budgetUsed,
                burnoutDeepened: ds.burnoutDeepened,
                dividendExtracted: ds.dividendExtracted,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware CAD: English "C$1.40M", Spanish "1,40 M C$" (comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(2).replace(`.`, `,`)} M C$`;
            }
            return `${sign}C$${abs.toFixed(2)}M`;
        }

