            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`coverageDisplay`, `domainState.coverage`, (v) => {
                const card = document.querySelector(`.lakesim-card-coverage`);
                if (card) {
                    card.classList.toggle(`lakesim-coverage-danger`, Number(v) < 70);
                    card.classList.toggle(`lakesim-coverage-safe`, Number(v) >= 90);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`wellbeingDisplay`, `domainState.wellbeing`, (v) => {
                const card = document.querySelector(`.lakesim-card-wellbeing`);
                if (card) {
                    card.classList.toggle(`lakesim-wellbeing-danger`, Number(v) < 50);
                    card.classList.toggle(`lakesim-wellbeing-safe`, Number(v) >= self.WELLBEING_TARGET);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`retentionDisplay`, `domainState.retention`, (v) => {
                const card = document.querySelector(`.lakesim-card-retention`);
                if (card) {
                    card.classList.toggle(`lakesim-retention-high`, Number(v) >= 60);
                    card.classList.toggle(`lakesim-retention-low`, Number(v) <= 30);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`trustDisplay`, `domainState.trust`, (v) => Math.round(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.STAB_BUDGET);
            });

            // Retention-cliff slider readout.
            const cl = document.getElementById(`cliffInput`);
            const clReadout = document.getElementById(`cliffReadout`);
            if (cl && clReadout) {
                clReadout.textContent = cl.value;
                cl.addEventListener(`input`, function() { clReadout.textContent = cl.value; });
            }

            // Stabilisation-budget live total (must hit CAD 1.4M).
            const allocIds = [`preceptInput`, `alliedInput`, `retainInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 100) / 100;
                if (allocReadout) allocReadout.textContent = total.toFixed(2);
                const bar = document.querySelector(`.lakesim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.STAB_BUDGET) > 0.001) ? `#d14343` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

