        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.coverageHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                lakeChart: {
