        _composite(ds) {
            // v1.0.0 composite formula, verbatim — single source of truth.
            const coverage = Math.round(ds.coverage);
            const wellbeing = Math.round(ds.wellbeing);
            const retention = Math.round(ds.retention);
            const trust = Math.round(ds.trust);
            return Math.round(coverage * 0.30 + wellbeing * 0.28 + (100 - retention) * 0.22 + trust * 0.20);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const coverage = Math.round(ds.coverage);
            const wellbeing = Math.round(ds.wellbeing);
            const retention = Math.round(ds.retention);
            const trust = Math.round(ds.trust);

            // Composite: balanced across the four KPIs (retention inverted).
            const composite = this._composite(ds);

            const safe = coverage >= 85;
            const recovering = wellbeing >= this.WELLBEING_TARGET;
            const held = retention <= 35;
            const trusted = trust >= 60;

            let performanceKey = `grade_unresolved`;
            if (safe && recovering && held && trusted && composite >= 78) performanceKey = `grade_stabilised`;
            else if (safe && trusted && wellbeing >= 55) performanceKey = `grade_safe`;
            else if (ds.burnoutDeepened && wellbeing < 45) performanceKey = `grade_burnout`;
            else if (ds.dividendExtracted && trust < 35) performanceKey = `grade_trustbroken`;
            else if (ds.throughputOnly && wellbeing < 50) performanceKey = `grade_wonquarter`;
            else if (composite >= 58) performanceKey = `grade_mixed`;
            const met = safe && recovering && held && trusted && composite >= 78;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (safe && recovering && held && trusted) insights.push(window.mySimulation.t(`insight_resilient`));
            else if (ds.burnoutDeepened) insights.push(window.mySimulation.t(`insight_burnout`));
            else if (ds.dividendExtracted) insights.push(window.mySimulation.t(`insight_extracted`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.chasedAgency) insights.push(window.mySimulation.t(`insight_agency`));
            if (ds.throughputOnly) insights.push(window.mySimulation.t(`insight_throughput`));
            if (ds.aiSilverBullet) insights.push(window.mySimulation.t(`insight_silverbullet`));
            if (recovering && trusted) insights.push(window.mySimulation.t(`insight_wellbeing`));

            return {
                coverage: coverage,
                wellbeing: wellbeing,
                retention: retention,
                trust: trust,
                safe: safe,
                recovering: recovering,
                held: held,
                trusted: trusted,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                burnoutDeepened: !!ds.burnoutDeepened,
                dividendExtracted: !!ds.dividendExtracted,
                throughputOnly: !!ds.throughputOnly,
                chasedAgency: !!ds.chasedAgency,
                aiSilverBullet: !!ds.aiSilverBullet,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="lakesim-cm-badge ` + (s.met ? `lakesim-cm-met` : `lakesim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.burnoutDeepened) badges.push(`<span class="lakesim-cm-badge lakesim-cm-fail">` + t(`cm_fail_burnout`) + `</span>`);
            if (s.dividendExtracted) badges.push(`<span class="lakesim-cm-badge lakesim-cm-fail">` + t(`cm_fail_extract`) + `</span>`);
            if (s.throughputOnly) badges.push(`<span class="lakesim-cm-badge lakesim-cm-fail">` + t(`cm_fail_throughput`) + `</span>`);
            if (s.chasedAgency) badges.push(`<span class="lakesim-cm-badge lakesim-cm-fail">` + t(`cm_fail_agency`) + `</span>`);
            if (s.aiSilverBullet) badges.push(`<span class="lakesim-cm-badge lakesim-cm-fail">` + t(`cm_fail_silver`) + `</span>`);
            const kpi = (label, val) => `<div class="lakesim-cm-metric"><div class="lakesim-cm-metric-val">` + val + `</div><div class="lakesim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_coverage`), (s.coverage != null ? Math.round(s.coverage) : 0) + `%`)
                + kpi(t(`cm_wellbeing`), (s.wellbeing != null ? Math.round(s.wellbeing) : 0))
                + kpi(t(`cm_retention`), (s.retention != null ? Math.round(s.retention) : 0))
                + kpi(t(`cm_trust`), (s.trust != null ? Math.round(s.trust) : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="lakesim-cm">`
                + `<div class="lakesim-cm-head"><div class="lakesim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="lakesim-cm-scorewrap"><span class="lakesim-cm-score">` + score + `</span><span class="lakesim-cm-score-max">/100</span></div>`
                + `<div class="lakesim-cm-grade">` + grade + `</div>`
                + `<div class="lakesim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="lakesim-cm-metrics">` + kpis + `</div>`
                + `<div class="lakesim-cm-insights"><div class="lakesim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
