            if (ds.dividendExtracted) return window.mySimulation.t(`hint_extract`);
            if (ds.burnoutDeepened && ds.wellbeing < 45) return window.mySimulation.t(`hint_burnout`);
            if (ds.chasedAgency && state.currentPeriod >= 2) return window.mySimulation.t(`hint_agency`);
            if (ds.coverage < 70 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_coverage`);
            if (ds.trust < 35 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_trust`);
            if (ds.coverage >= 85 && ds.wellbeing >= this.WELLBEING_TARGET && ds.trust >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

